-- Questões originais: Fernandes e Abreu, Implantando a Governança de TI, 4ª edição, Brasport, 2014.
-- Contexto histórico da edição: COBIT 5, ITIL 2011 e versões de normas nela apresentadas.
-- Não são questões oficiais nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 4: Os Papéis da Governança de TI na Organização — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('97ab0c17-e0a1-5959-bacf-938b42e7b665', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Governança de TI', 'Fácil', 'Segundo o capítulo sobre papéis, a indefinição de responsabilidades constitui:', '["Forma obrigatória de governança.","Prova de maturidade elevada.","Obstáculo à implantação da governança.","Substituto de comitês.","Garantia de flexibilidade eficaz."]'::jsonb, 2, 'Sem clareza sobre quem faz o quê, ações podem ficar sem responsável.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6dcc5977-6983-53f6-8a23-7492b2c19406', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Governança de TI', 'Médio', 'Qual critério deve orientar a escolha da estrutura de governança?', '["Número de páginas do COBIT.","Popularidade do organograma.","Características e momento da organização.","Quantidade de ferramentas instaladas.","Preferência exclusiva de consultores."]'::jsonb, 2, 'Não há um único arquétipo superior para todos os contextos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a39366d6-1cf9-5358-983e-00e39ec6992c', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Governança de TI', 'Fácil', 'A criação de um departamento específico de governança é a única abordagem admitida pelos autores?', '["Sim, desde que vinculado ao fornecedor.","Não; existem programas, profissionais designados e outros arranjos.","Sim, com estrutura sempre idêntica.","Sim, inclusive para qualquer microempresa.","Não, porque departamentos são proibidos."]'::jsonb, 1, 'O capítulo descreve alternativas organizacionais.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c3d64980-3b05-5b1d-b3d1-e4fd6a73ea8c', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Governança de TI', 'Médio', 'Em uma grande organização, a área de governança pode atuar principalmente por:', '["Execução exclusiva de todo suporte.","Indução, promoção e visibilidade para o CIO.","Substituição de todas as gerências.","Aprovação de leis externas.","Operação de cada sistema corporativo."]'::jsonb, 1, 'Os autores discutem atuação de influência e informação para apoiar a intervenção do CIO.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('63b2cf29-b6ac-5e9b-ad91-38a93ae51d15', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Governança de TI', 'Médio', 'No modelo de programa, quando pode terminar a estrutura temporária de implantação?', '["Assim que a ferramenta for comprada.","Somente quando a empresa fechar.","Antes de definir responsáveis.","Quando os objetivos previstos de maturidade forem alcançados.","Quando cessarem todas as demandas de TI."]'::jsonb, 3, 'Encerrar o programa não elimina a manutenção das práticas implantadas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('201e8ea9-6ea7-5479-bc76-e6d6f5c00dd6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Governança de TI', 'Fácil', 'Quem mantém efetivamente as boas práticas nas áreas operacionais?', '["Apenas a diretoria financeira.","Exclusivamente os clientes.","As próprias áreas funcionais de TI.","Somente a consultoria contratada.","Somente o auditor externo."]'::jsonb, 2, 'A governança é compartilhada e depende da atuação das áreas de TI.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fa78b240-9bfa-5c88-b59b-061ec51a42d6', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Governança de TI', 'Médio', 'Na distribuição proposta, quem aprova a política corporativa de risco e compliance?', '["Apenas o fornecedor de infraestrutura.","Diretoria executiva.","Exclusivamente cada usuário.","Somente central de serviços.","Somente equipe de testes."]'::jsonb, 1, 'A alta direção estabelece a política corporativa.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a0d2369e-dece-554c-8948-cc0296d7edfa', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Governança de TI', 'Médio', 'Quem deve fazer a TI seguir a política corporativa de risco e acompanhar sua exposição?', '["Apenas equipe de publicidade.","Somente usuários externos.","Exclusivamente o fabricante.","CIO.","Apenas o recepcionista."]'::jsonb, 3, 'O CIO responde pelo cumprimento e acompanhamento no âmbito da TI.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d5b6bc23-555e-5484-bd17-70cad99c84ac', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Governança de TI', 'Médio', 'As áreas funcionais detectaram um risco em seus serviços. Qual papel lhes cabe no modelo?', '["Suspender os indicadores.","Desenvolver e implantar ações de mitigação.","Transferir toda execução à diretoria.","Somente aguardar uma auditoria.","Alterar a política sem autorização."]'::jsonb, 1, 'As áreas implementam as respostas em seus processos e recursos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('370d3ad3-2dde-5b09-8ad5-389b5fdee2db', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Governança de TI', 'Médio', 'Verificar se as ações de mitigação foram efetivas é papel atribuído também às áreas de:', '["Somente compras de material.","Somente administração predial.","Apenas atendimento externo.","Exclusivamente comunicação visual.","Controle, risco e compliance."]'::jsonb, 4, 'A verificação complementa a execução das ações pelas áreas de TI.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a85b8eb2-6134-58df-92b7-23bd8aad2828', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Governança de TI', 'Médio', 'Na avaliação independente, as áreas funcionais devem principalmente:', '["Substituir a auditoria por autodeclaração.","Eliminar evidências de desvio.","Resolver as não conformidades sob sua responsabilidade.","Apenas aprovar a política corporativa.","Definir unilateralmente o escopo regulatório."]'::jsonb, 2, 'A correção dos itens deve ocorrer nas áreas responsáveis.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('59883e79-943e-578e-b34b-a279ffe12f2b', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Governança de TI', 'Médio', 'Na proposta de alinhamento, quem define e comunica a estratégia da organização?', '["Diretoria executiva.","Apenas consultoria de certificação.","Exclusivamente equipe de rede.","Somente central de serviços.","Somente fornecedor estratégico."]'::jsonb, 0, 'A estratégia corporativa direciona as estratégias de TI.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ad62c7cf-7619-5808-b88b-249404c5f1a3', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Governança de TI', 'Médio', 'Consolidar o orçamento de TI e estruturar o portfólio são contribuições propostas para qual área?', '["Governança de TI.","Somente auditoria externa.","Exclusivamente usuários finais.","Apenas manutenção predial.","Somente marketing corporativo."]'::jsonb, 0, 'A área pode apoiar o planejamento e sua integração.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('befff358-f173-5d02-88cf-c3e790d4099b', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Governança de TI', 'Médio', 'Na entrega de valor, qual atuação cabe às áreas funcionais de TI?', '["Definir sozinhas todas as prioridades corporativas.","Apenas observar os dashboards.","Somente aprovar a estratégia corporativa.","Desenvolver projetos e fornecer serviços conforme os planos.","Exclusivamente auditar o CIO."]'::jsonb, 3, 'A execução nas áreas materializa projetos, serviços e inovações.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ad9c7946-eca6-57f2-83c2-96632b18258c', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Governança de TI', 'Médio', 'Ao identificar oportunidade de otimização de recursos, a governança deve:', '["Acompanhar e recomendar ações com visibilidade gerencial.","Substituir todos os fornecedores imediatamente.","Suspender a comunicação ao CIO.","Eliminar o controle das áreas.","Comprar recursos sem orçamento."]'::jsonb, 0, 'Seu papel inclui identificar oportunidades e acompanhar recursos e investimentos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d4d863d0-9f41-51d9-b377-d700f8587d0b', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Governança de TI', 'Médio', 'Quem fornece indicadores sobre seus projetos e serviços à governança e ao CIO?', '["Somente clientes potenciais.","Exclusivamente os concorrentes.","Somente acionistas externos.","Áreas funcionais de TI.","Apenas o órgão regulador."]'::jsonb, 3, 'A informação de desempenho nasce também das áreas que executam o trabalho.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('49f53c9f-5577-5d9a-96ac-476b5454657c', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Governança de TI', 'Médio', 'Manter o dashboard de governança integra qual responsabilidade proposta?', '["Substituir a contabilidade.","Definir requisitos legais externos.","Executar todas as mudanças de produção.","Aprovar a política societária.","Consolidar e comunicar desempenho e valor."]'::jsonb, 4, 'O painel dá visibilidade para decisões e acompanhamento.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c08b8570-e07a-5b4f-844a-48448c511f48', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Governança de TI', 'Difícil', 'Uma área de governança acompanha indicadores, mas o CIO nunca atua sobre desvios. Qual lacuna persiste?', '["Uso das informações para dirigir e corrigir a gestão.","Ausência obrigatória de mais ferramentas.","Necessidade de extinguir as áreas funcionais.","Excesso de independência dos usuários.","Falta automática de auditor externo."]'::jsonb, 0, 'Visibilidade precisa alimentar ações e decisões dos responsáveis.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4dbfd3ee-5cf1-57dd-ba7f-b29b4a756fcf', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Governança de TI', 'Difícil', 'Delegar a implantação das práticas a uma consultoria dispensa o envolvimento das áreas de TI?', '["Não, porque consultoria é proibida.","Sim, se houver um departamento de governança.","Sim, durante toda a vigência do contrato.","Sim, se o consultor tiver certificação.","Não; elas precisam adotar e sustentar as práticas."]'::jsonb, 4, 'A execução e a continuidade dependem da organização que utilizará os processos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf2e9688-f1d1-5baa-99a6-2d6faf514be5', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Governança de TI', 'Médio', 'Um programa de mudança envolve processos de várias gerências. Qual arranjo é coerente com o capítulo?', '["Responsabilidade exclusiva dos usuários externos.","Ausência de patrocinador definido.","Execução sem comunicação aos gestores.","Atuação isolada de um analista.","Liderança do CIO e participação das áreas afetadas."]'::jsonb, 4, 'A liderança e a participação sustentam a implantação transversal.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 4, páginas 211–214 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
